from pathlib import Path
import html,json
SITE=Path(__file__).resolve().parents[1]; DIST=SITE/'dist'
book=json.loads((DIST/'book.json').read_text())
visuals={'cover':'office-overview.png','office':'office-overview.png','office-fleet':'office-fleet.png','mine':'mine-team.png','apartment':'apartment-team.png','ppo-completed':'ppo-completed.png','gazebo':'03-gazebo-overview.png','gazebo-top':'07-gazebo-top.png','rviz':'10-rviz-progress.png','closing':'ppo-completed.png'}
styles='''@page{size:A4;margin:18mm 17mm 17mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#24392b;font-size:10.4pt;line-height:1.65;margin:0}section{break-after:page;min-height:245mm}section:last-child{break-after:auto}.running{font:7pt monospace;letter-spacing:1.5px;text-transform:uppercase;color:#819273;border-bottom:1px solid #d6dfc8;padding-bottom:12px;margin-bottom:25px;display:flex;justify-content:space-between}h1{font-family:Georgia,serif;font-weight:400;font-size:31pt;line-height:1.12;letter-spacing:-1px;margin:0 0 10px}.deck{color:#809271;font-size:11pt;margin:0 0 23px}.columns{display:grid;grid-template-columns:1.2fr 1fr;gap:24px}.notes{border-left:1px solid #dce2d1;padding-left:22px;font-size:9.5pt}h3{font:18pt Georgia,serif;margin:18px 0 10px}p{margin:0 0 13px}strong{font-weight:600}ul{padding-left:17px}li{margin-bottom:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:7.7pt/1.7 monospace;padding:13px;background:#eef2e6;border:1px solid #dce5d0}table{border-collapse:collapse;width:100%;font-size:8pt;line-height:1.5;margin-bottom:17px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #d9e1cc;padding:7px 5px}th{font-size:7pt;color:#82936f}tr:nth-child(even){background:#f0f3e8}img{max-width:100%;height:auto;border:1px solid #d9e1cd;margin-bottom:15px}a{color:#a8633e;text-decoration:none}.sources{font:6.8pt/1.7 monospace;overflow-wrap:anywhere;border-top:1px solid #dce2d1;padding-top:12px;margin-top:20px;color:#7c8e69}.tag{font:6.5pt monospace;letter-spacing:1px;color:#a76b43;margin-bottom:9px}.cover h1{font-size:54pt}.cover p{font-size:9.5pt;margin-bottom:10px}.cover .deck{font-size:15pt}.cover .columns{display:block}.cover .notes{border:0;padding:0}.cover img{max-width:100mm;max-height:58mm;object-fit:contain}.team{font-size:10pt;margin:20px 0}.colophon{font-size:7.5pt;color:#889678;margin-top:15px}.illustration{padding:15px;background:#eef2e5;border:1px solid #d4dfc4;font:8pt/1.8 monospace;margin-bottom:17px}.illustration strong{color:#b46a42}'''
out='<!doctype html><html lang="en"><meta charset="utf-8"><title>SWARM SAR — The Fieldbook</title><style>'+styles+'</style><body>'
for p in book['pages']:
    out+=f'<section class="{"cover" if p["kind"]=="cover" else ""}"><div class="running"><span>SWARM SAR / THE FIELDBOOK</span><span>{p["id"]+1:02d} / {len(book["pages"])}</span></div><h1>{html.escape(p["title"])}</h1><p class="deck">{p["deck"]}</p>'
    if p['kind']=='cover':out+='<p class="team">Om Rashiya · Yash Bharvada · Purva Shah · Pankti Akbari</p>'
    out+='<div class="columns"><div>'+p['body']+'</div><div class="notes">'
    if p['visual'] in visuals:out+='<p class="tag">REAL PROJECT CAPTURE</p><img src="assets/'+visuals[p['visual']]+'" alt="Original project capture">'
    elif p['visual']=='training-pipeline':out+='<div class="illustration">EXPERT DEMONSTRATIONS<br>↓<br>RECURRENT BEHAVIOR CLONING<br>↓<br><strong>PPO PRACTICE</strong><br>↓<br>COHORTS → GATES → HANDOFF</div>'
    elif p['visual']=='learning-loop':out+='<div class="illustration">OBSERVATION → POLICY → ACTION<br>↑　　　　　　　　　　↓<br>← REWARD ← ENVIRONMENT</div>'
    elif p['visual']=='actor-critic':out+='<div class="illustration">LOCAL OBSERVATION<br>↙　　　　　↘<br>ACTOR　　　 CRITIC<br>Actions　　 Expected return</div>'
    out+=p['notes']
    out+='<div class="sources">PROJECT SOURCES<br>'+''.join('<a href="https://github.com/rashiyaom/swarm-sar/blob/'+book['revision']+'/'+path+'">'+html.escape(path)+'</a><br>' for path in p['sources'])+'</div></div></div>'
    if p['kind']=='cover':out+='<div class="colophon">30 October 2026 · Illustrated English audio edition<br>Source revision: '+book['revision']+'<br>The web edition includes interactive teaching diagrams, source browsing, bookmarks and page narration.<br>Synthetic English narration: Samantha, generated using macOS system text-to-speech.</div>'
    out+='</section>'
out+='</body></html>'
(DIST/'print.html').write_text(out)
print('Prepared complete illustrated print edition.')
